/**
 * Extract Call ID and prepare for tracking
 * ElevenLabs returns: { conversation_id: "conv_abc123", status: "initiated" }
 */

const elevenlabsResponse = $input.first().json;
const appointmentData = $('Loop: Each Patient').first().json;

return [{
  json: {
    // ElevenLabs call data
    callId: elevenlabsResponse.conversation_id || elevenlabsResponse.id,
    callStatus: elevenlabsResponse.status || "initiated",

    // Appointment data for later update
    Appointment_Uid: appointmentData.Appointment_Uid,
    Patient_Name: appointmentData.Patient_Name,
    Patient_Phone: appointmentData.Patient_Phone,
    Patient_Email: appointmentData.Patient_Email,
    Date: appointmentData.Date,
    Time: appointmentData.Time,
    formattedDate: appointmentData.formattedDate,
    formattedTime: appointmentData.formattedTime,

    // Timestamp
    callInitiatedAt: new Date().toISOString()
  }
}];

/**
 * Parse ElevenLabs webhook callback
 * 
 * ElevenLabs sends:
 * {
 *   "conversation_id": "conv_abc123",
 *   "status": "ended",
 *   "phone_number": "+15551234567",
 *   "end_reason": "user_ended",
 *   "transcript": [
 *     {"role": "agent", "message": "Hi John..."},
 *     {"role": "user", "message": "Yes, I'll be there"}
 *   ],
 *   "analysis": {
 *     "summary": "Patient confirmed attendance",
 *     "sentiment": "positive"
 *   },
 *   "recording_url": "https://elevenlabs.io/recording/abc123"
 * }
 */

const webhookData = $input.first().json;

// Extract transcript from ElevenLabs format
let transcript = "";
if (Array.isArray(webhookData.transcript)) {
  transcript = webhookData.transcript
    .map(msg => `${msg.role}: ${msg.message}`)
    .join('\n');
} else if (typeof webhookData.transcript === 'string') {
  transcript = webhookData.transcript;
} else {
  transcript = "No transcript available";
}

const summary = webhookData.analysis?.summary || webhookData.summary || "";
const status = webhookData.status || "unknown";
const endReason = webhookData.end_reason || webhookData.endReason || "";

// Determine action taken based on transcript analysis
let actionTaken = "Unknown";
let patientConfirmed = false;

const transcriptLower = transcript.toLowerCase();
const summaryLower = summary.toLowerCase();

// Check for confirmation
if (transcriptLower.includes("confirmed") || transcriptLower.includes("see you") || 
    transcriptLower.includes("i'll be there") || transcriptLower.includes("yes") ||
    transcriptLower.includes("i will be there") || summaryLower.includes("confirmed")) {
  actionTaken = "Confirmed";
  patientConfirmed = true;
}
// Check for cancellation/reschedule
else if (transcriptLower.includes("cancel") || transcriptLower.includes("reschedule") ||
         transcriptLower.includes("can't make it") || transcriptLower.includes("cannot make it") ||
         transcriptLower.includes("sending you") || summaryLower.includes("cancel") || 
         summaryLower.includes("reschedule")) {
  actionTaken = "Sent Cal.com Link";
  patientConfirmed = false;
}
// Check for voicemail
else if (transcriptLower.includes("voicemail") || transcriptLower.includes("call us back") ||
         endReason === "voicemail" || summaryLower.includes("voicemail")) {
  actionTaken = "Voicemail Left";
  patientConfirmed = false;
}
// No answer
else if (status === "no-answer" || endReason === "no_answer" || endReason === "no-answer" ||
         summaryLower.includes("no answer")) {
  actionTaken = "No Answer";
  patientConfirmed = false;
}
// Call completed but unclear outcome
else if (status === "ended" || status === "completed") {
  actionTaken = "Call Completed - Unclear Response";
  patientConfirmed = false;
}

console.log(`
📞 Call Analysis (ElevenLabs):
  - Conversation ID: ${webhookData.conversation_id}
  - Status: ${status}
  - Action Taken: ${actionTaken}
  - Confirmed: ${patientConfirmed}
  - Transcript: ${transcript.substring(0, 200)}...
`);

return [{
  json: {
    callId: webhookData.conversation_id || webhookData.id,
    phoneNumber: webhookData.phone_number || webhookData.phoneNumber,
    callStatus: status,
    endedReason: endReason,
    actionTaken: actionTaken,
    patientConfirmed: patientConfirmed,
    transcript: transcript,
    summary: summary,
    recordingUrl: webhookData.recording_url || webhookData.recordingUrl || "",
    processedAt: new Date().toISOString()
  }
}];

