/**
 * Find appointment UID from Google Sheet based on phone number
 * (Needed because Vapi webhook doesn't include appointment UID)
 */

const phoneNumber = $input.first().json.phoneNumber;

// Read all appointments to find matching phone
const allAppointments = await $node["Read Appointments"].json();
const matchedAppt = allAppointments.find(appt => appt.Patient_Phone === phoneNumber);

if (!matchedAppt) {
  console.warn(`⚠️ No appointment found for phone: ${phoneNumber}`);
  return [{
    json: {
      ...$input.first().json,
      Appointment_Uid: "UNKNOWN",
      Patient_Email: "unknown@example.com"
    }
  }];
}

return [{
  json: {
    ...$input.first().json,
    Appointment_Uid: matchedAppt.Appointment_Uid,
    Patient_Email: matchedAppt.Patient_Email,
    Patient_Name: matchedAppt.Patient_Name,
    Date: matchedAppt.Date,
    Time: matchedAppt.Time
  }
}];
